"""Frozen oracle for harken's Hacker News and Bluesky normalisation, from the unmodified donor.

python harken_sources_oracle.py <harken checkout at d0710a42> <out.json>
HackerNewsSource.fetch_page and BlueskySource.fetch_page run unmodified; only the instance's
_client factory is replaced by one that returns a captured API body, so no network is used.
"""
import hashlib, json, pathlib, random, subprocess, sys

donor = pathlib.Path(sys.argv[1]).resolve(); out = pathlib.Path(sys.argv[2])
git = lambda *a: subprocess.check_output(["git", "-C", str(donor), *a], text=True).strip()
commit = git("rev-parse", "HEAD"); assert commit == "d0710a427dbbe712594ef3a6c25112e1d14cc027"
assert not git("status", "--porcelain")
sys.path.insert(0, str(donor / "src"))
from harken.sources.hackernews import HackerNewsSource  # noqa: E402
from harken.sources.bluesky import BlueskySource  # noqa: E402
import httpx, pydantic  # noqa: E402


class Captured:
    def __init__(self, body): self.body = body
    def __enter__(self): return self
    def __exit__(self, *a): return False
    def get(self, url, params=None):
        return httpx.Response(200, json=self.body, request=httpx.Request("GET", url, params=params))


def run(source, query, body):
    source._client = lambda **kw: Captured(body)
    page = source.fetch_page(query, limit=100)
    return [{"author": m.author, "title": m.title, "text": m.text, "url": m.url,
             "created_at": m.created_at.isoformat() if m.created_at else None, "score": m.score} for m in page.mentions]


rng = random.Random(9071)
words = ["matcha", "whisk", "bamboo", "tea", "cup", "kettle", "ceramic"]
html_bits = ["<p>", "</p>", "<i>", "</i>", "&amp;", "&#x27;", "&quot;", "<a href=\"https://x.example/\">link</a>", "\n", "  "]
cases = []
for i in range(120):
    hits = []
    for n in range(rng.randint(0, 6)):
        hit = {"objectID": str(rng.randint(1, 10**8)), "author": rng.choice(["alice", "bob", None]), "points": rng.choice([None, 0, rng.randint(1, 500)])}
        if rng.random() < 0.85: hit["created_at_i"] = rng.randint(1_600_000_000, 1_800_000_000)
        if rng.random() < 0.5: hit["title"] = " ".join(rng.choice(words) for _ in range(rng.randint(1, 4)))
        else: hit["story_title"] = " ".join(rng.choice(words) for _ in range(rng.randint(1, 4)))
        if rng.random() < 0.6: hit["comment_text"] = "".join(rng.choice(words + html_bits) + " " for _ in range(rng.randint(1, 8)))
        hits.append(hit)
    body = {"hits": hits, "page": 0, "nbPages": 1}
    cases.append({"case_id": f"hn-{i}", "platform": "HACKER_NEWS", "query": "matcha", "raw": body, "mentions": run(HackerNewsSource(), "matcha", body)})
for i in range(120):
    posts = []
    for n in range(rng.randint(0, 6)):
        handle = rng.choice(["a.bsky.social", "shop.example"])
        rkey = "3k" + "".join(rng.choice("abcdefghij234567") for _ in range(11))
        rec = {"text": " ".join(rng.choice(words) for _ in range(rng.randint(1, 6)))}
        if rng.random() < 0.8: rec["createdAt"] = f"2026-0{rng.randint(1,9)}-1{rng.randint(0,9)}T0{rng.randint(0,9)}:00:00.000Z"
        post = {"uri": f"at://did:plc:{rng.randint(1,999)}/app.bsky.feed.post/{rkey}", "author": {"did": f"did:plc:{rng.randint(1,999)}", "handle": handle}, "record": rec, "likeCount": rng.choice([None, 0, rng.randint(1, 900)])}
        if rng.random() < 0.5: post["indexedAt"] = f"2026-0{rng.randint(1,9)}-2{rng.randint(0,8)}T1{rng.randint(0,9)}:30:00.000Z"
        posts.append(post)
    body = {"posts": posts}
    cases.append({"case_id": f"bsky-{i}", "platform": "BLUESKY", "query": "matcha", "raw": body, "mentions": run(BlueskySource(), "matcha", body)})
generator = pathlib.Path(__file__).read_bytes()
ev = lambda p: {"path": p, "blob_hash": git("rev-parse", f"{commit}:{p}"), "sha256": hashlib.sha256(subprocess.check_output(["git", "-C", str(donor), "show", f"{commit}:{p}"])).hexdigest()}
out.write_text(json.dumps({"donor_id": "VladUZH--harken", "commit_sha": commit, "license": "MIT", "oracle": "UNMODIFIED_DONOR_SOURCES_CAPTURED_BODIES",
    "python_httpx": httpx.__version__, "pydantic": pydantic.VERSION,
    "source_evidence": [ev(p) for p in ["src/harken/sources/hackernews.py", "src/harken/sources/bluesky.py", "src/harken/sources/base.py", "src/harken/models.py", "LICENSE"]],
    "generator_sha256": hashlib.sha256(generator).hexdigest(), "generator_source": generator.decode(), "cases": cases}, indent=1, ensure_ascii=False) + "\n")
print(len(cases), "cases;", sum(len(c["mentions"]) for c in cases), "donor mentions")
